const check=r=>{if(r.error)throw r.error;return r.data};
const nameOf=id=>P.profiles.find(p=>p.id===id)||{id,username:'unknown',display_name:'Пользователь',bio:''};
const initials=p=>(p?.display_name||'?').trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();
