const badgeType=id=>P.moderators.some(m=>m.user_id===id)?'moderator':P.verified.find(v=>v.profile_id===id)?.badge_type||null;
const badge=id=>{const type=badgeType(id);if(!type)return '';const label=type==='moderator'?'Модератор проекта Pear':type==='green'?'Разработчик проекта Pear':'Подтверждённый профиль',file=type==='moderator'?'verified-moderator.png':type==='green'?'verified-green.png':'verified.png';return `<img class="verified-badge" src="/assets/${file}" alt="${label}" title="${label}">`};
function formatBody(text){const re=/(^|[^\p{L}\p{N}_@#])([@#])([\p{L}\p{N}_]{1,32})/gu;let out='',at=0;for(const m of String(text||'').matchAll(re)){out+=esc(text.slice(at,m.index))+esc(m[1]);let token=m[2]+m[3];if(m[2]==='#'){out+=`<button type="button" class="inline-link" data-hashtag="${esc(token)}">${esc(token)}</button>`}else{const exact=P.profiles.find(x=>x.username===m[3]),matches=P.profiles.filter(x=>x.username.toLowerCase()===m[3].toLowerCase()),a=exact||(matches.length===1?matches[0]:null);out+=a?`<button type="button" class="inline-link" data-profile="${esc(a.id)}">${esc(token)}</button>`:`<button type="button" class="inline-link" data-mention="${esc(m[3])}">${esc(token)}</button>`}at=m.index+m[0].length}return out+esc(String(text||'').slice(at))}
let profileTapCount=0,profileTapTimer=null;
function resetProfileTaps(){profileTapCount=0;clearTimeout(profileTapTimer);profileTapTimer=null}
function handleNavigation(page){
 if(page!=='profile'){resetProfileTaps();navigate(page);return}
 if(!P.isAdmin&&!P.isModerator){resetProfileTaps();navigate('profile');return}
 profileTapCount++;clearTimeout(profileTapTimer);
 if(profileTapCount>=3){resetProfileTaps();navigate('admin');return}
 profileTapTimer=setTimeout(resetProfileTaps,2500);
 if(P.page!=='profile'||P.profileId!==P.session?.user?.id)navigate('profile');
}
function syncAdminNav(){document.querySelectorAll('[data-nav=admin]').forEach(b=>b.remove());document.querySelector('.nav-mobile')?.classList.remove('has-admin');if(!P.isAdmin&&!P.isModerator)resetProfileTaps();updateNav()}

const date=d=>{let v=new Date(d);return isNaN(v)?'':new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(v)};
function toast(text){document.querySelector('.toast')?.remove();let n=document.createElement('div');n.className='toast';n.role='status';n.textContent=text;document.body.append(n);setTimeout(()=>n.remove(),3500)}
function error(text){const n=document.querySelector('.overlay #error')||document.getElementById('error');if(n){n.textContent=text;n.hidden=false}else toast(text)}
function selectedNav(n){return (P.page===n?'active':'')}
