function createShell(){root.innerHTML=`<div class="app"><aside class="left"><nav class="nav" aria-label="Основная навигация"><button data-nav="feed" title="Лента" aria-label="Лента">${icon('home')}<span class="nav-text">Лента</span></button><button data-nav="search" title="Поиск" aria-label="Поиск">${icon('search')}<span class="nav-text">Поиск</span></button><button data-nav="notifications" title="Уведомления" aria-label="Уведомления">${icon('bell')}<span class="nav-text">Уведомления</span><span class="notification-count" hidden></span></button><button data-nav="chat" title="Сообщения" aria-label="Сообщения">${icon('chat')}<span class="nav-text">Сообщения</span><span class="nav-unread" aria-hidden="true" hidden></span></button><button data-nav="profile" title="Мой профиль" aria-label="Мой профиль">${icon('user')}<span class="nav-text">Мой профиль</span></button></nav><button class="nav-create" data-compose title="Создать пост" aria-label="Создать пост">${icon('plus')}<span class="nav-create-label">Создать пост</span></button><div class="account" id="account"></div></aside><div class="center-column"><div class="center-toolbar"><form id="side-search" class="center-search" role="search"><span class="center-search-icon" aria-hidden="true">${icon('search')}</span><input class="search" name="query" placeholder="Поиск по Pear" aria-label="Поиск по Pear"><button type="submit" class="search-submit" aria-label="Найти">${icon('search')}<span>Найти</span></button></form><button data-nav="notifications" class="notifications-open" type="button" aria-label="Уведомления" title="Уведомления">${icon('bell')}<span class="notification-count" hidden></span></button><button class="settings-open" type="button" aria-label="Настройки" title="Настройки"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1.2l1.7-1.3-1.7-3-2 .8a7.6 7.6 0 0 0-2-1.1L14.6 4h-3.2l-.4 2.2A7.6 7.6 0 0 0 9 7.3l-2-.8-1.7 3L7 10.8a7.2 7.2 0 0 0 0 2.4l-1.7 1.3 1.7 3 2-.8a7.6 7.6 0 0 0 2 1.1l.4 2.2h3.2l.4-2.2a7.6 7.6 0 0 0 2-1.1l2 .8 1.7-3-1.7-1.3A7 7 0 0 0 19 12Z"/></svg></button></div><main class="main" id="main"><div class="empty">Загружаем публикации…</div></main><footer class="pear-footer"><span>© ${new Date().getFullYear()} Pear</span><span>Лицензия и правила: информация уточняется</span></footer></div></div><nav class="nav-mobile" aria-label="Навигация"><button data-nav="feed" aria-label="Лента">${icon('home')}</button><button data-nav="search" aria-label="Поиск">${icon('search')}</button><button class="create" data-compose aria-label="Создать пост">${icon('plus')}</button><button data-nav="chat" aria-label="Сообщения">${icon('chat')}<span class="nav-unread" aria-hidden="true" hidden></span></button><button data-nav="profile" aria-label="Профиль">${icon('user')}</button></nav>`;
root.querySelector('.settings-open').onclick=Appearance.open;root.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>handleNavigation(b.dataset.nav));root.querySelectorAll('[data-compose]').forEach(b=>b.onclick=compose);root.querySelector('#side-search').onsubmit=ev=>{ev.preventDefault();P.query=ev.currentTarget.elements.query.value.trim();P.page='search';saveLocation();updateNav();draw();Chats.onNavigate()};updateNav();updateAccount()}
function updateAccount(){const a=document.getElementById('account');if(!a)return;const me=P.me||nameOf(P.session?.user.id);a.innerHTML=`${avatar(me)}<div class="grow"><div class="account-name">${esc(me.display_name)}</div><div class="account-handle">@${esc(me.username)}</div></div><button class="logout" title="Выйти" aria-label="Выйти">${icon('logout')}</button>`;a.querySelector('button').onclick=async()=>{const {error:err}=await P.client.auth.signOut();if(err)toast(err.message)}}
function showUnread(count){root.querySelectorAll('[data-nav="chat"]').forEach(button=>{const badge=button.querySelector('.nav-unread');if(!badge)return;badge.hidden=count===0;badge.textContent=count>99?'99+':String(count);const label=count?`Сообщения, непрочитанных: ${count}`:'Сообщения';button.setAttribute('aria-label',label);if(button.hasAttribute('title'))button.title=label})}
function updateNav(){root.querySelectorAll('[data-nav]').forEach(b=>{let on=b.dataset.nav===P.page;b.classList.toggle('active',on);on?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current')});const search=root.querySelector('#side-search');if(search)search.hidden=P.page==='search'}
// Remember only navigation state for this signed-in user and this browser tab.
function saveLocation(){if(!P.session?.user?.id)return;try{sessionStorage.setItem('pear.location.v1:'+P.session.user.id,JSON.stringify({page:P.page,profileId:P.profileId,postId:P.postId,chatId:Chats.getSelectedId(),tab:P.tab,query:P.query,adminQuery:P.adminQuery}))}catch(_){/* Browsing works even if storage is unavailable. */}}
function restoreLocation(uid){try{const state=JSON.parse(sessionStorage.getItem('pear.location.v1:'+uid)||'null');if(!state||typeof state!=='object')return;const uuid=x=>typeof x==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(x);if(['feed','search','profile','chat','admin','notifications','post'].includes(state.page))P.page=state.page;if(uuid(state.profileId))P.profileId=state.profileId;if(uuid(state.postId)){P.postId=state.postId;if(P.page==='post')P.expanded.add(state.postId)}else if(P.page==='post')P.page='feed';if(['new','trends','following'].includes(state.tab))P.tab=state.tab;if(typeof state.query==='string')P.query=state.query.slice(0,200);if(typeof state.adminQuery==='string')P.adminQuery=state.adminQuery.slice(0,200);if(uuid(state.chatId))Chats.restoreSelection(state.chatId)}catch(_){/* Invalid or unavailable saved state is ignored. */}}
function navigate(page,id){P.page=page;if(page==='profile')P.profileId=id||P.session.user.id;if(page==='post'){P.postId=id;P.detailPost=null;P.expanded.add(id)}if(page==='search')P.query='';saveLocation();updateNav();draw();Chats.onNavigate();if(page==='admin'){refreshAdminStats();refreshReports()}if(page==='profile'||page==='post')scheduleLoad(0);if(page==='notifications')Notifications.refresh();window.scrollTo({top:0,behavior:'instant'});if(page==='search' && window.matchMedia('(min-width: 661px)').matches) document.getElementById('q')?.focus()}
function dialog(title,html){document.querySelector('.overlay')?.remove();const wrap=document.createElement('div');wrap.className='overlay';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="close" aria-label="Закрыть">×</button></div><div class="error" id="error" hidden></div>${html}</section>`;document.body.append(wrap);wrap.querySelector('.close').onclick=()=>wrap.remove();wrap.onclick=ev=>{if(ev.target===wrap)wrap.remove()};wrap.onkeydown=ev=>{if(ev.key==='Escape')wrap.remove()};wrap.querySelector('textarea,input')?.focus();return wrap}
async function load(){if(!P.client||!P.session||P.pending)return;const seq=++P.fetchSeq,rev=P.revision;try{const [postsR,profilesR,followsR,verifiedR,adminR,pinsR,moderatorR]=await Promise.all([P.client.from('posts').select('*').order('created_at',{ascending:false}).limit(100),P.client.from('profiles').select('id,username,display_name,bio,avatar_path,banner_path').limit(1000),P.client.from('follows').select('follower_id,following_id').limit(1000),P.client.from('pear_verified_profiles').select('profile_id,badge_type').limit(10000),P.client.from('pear_admins').select('user_id').eq('user_id',P.session.user.id).limit(1),P.client.from('pear_pinned_posts').select('author_id,post_id,posts(*)').in('author_id',[...new Set([P.session.user.id,P.profileId].filter(Boolean))]).limit(2),P.client.from('pear_moderators').select('user_id').limit(10000)]);const detailResult=P.page==='post'&&P.postId?await P.client.from('posts').select('*').eq('id',P.postId).maybeSingle():{data:null,error:null};const detailPost=check(detailResult);const pins=pinsR.error?P.pins:(pinsR.data||[]),posts=check(postsR),profiles=check(profilesR),follows=check(followsR),verified=check(verifiedR),admins=check(adminR),ids=[...new Set([...posts.map(p=>p.id),...pins.filter(x=>x.posts).map(x=>x.post_id),...(detailPost?[detailPost.id]:[])])];let likes=[],comments=[],views=[];if(ids.length){const [l,c,v]=await Promise.all([P.client.from('likes').select('post_id,user_id').in('post_id',ids).limit(10000),P.client.from('comments').select('id,post_id,author_id,body,created_at,parent_id').in('post_id',ids).order('created_at').limit(10000),P.client.rpc('pear_post_view_counts',{p_post_ids:ids})]);likes=check(l);comments=check(c);views=check(v)}if(seq!==P.fetchSeq||rev!==P.revision||P.pending)return;const before=JSON.stringify([P.posts,P.detailPost,P.pins,P.profiles,P.likes,P.comments,P.follows,P.verified,P.views,P.isAdmin,P.isModerator,P.moderators,P.moderatorsError]);Object.assign(P,{posts,detailPost,pins,profiles,likes,comments,follows,verified,views,isAdmin:admins.length>0,moderators:moderatorR.error?[]:(moderatorR.data||[]),moderatorsError:!!moderatorR.error,isModerator:!moderatorR.error&&(moderatorR.data||[]).some(x=>x.user_id===P.session.user.id),loaded:true});P.me=nameOf(P.session.user.id);const after=JSON.stringify([P.posts,P.detailPost,P.pins,P.profiles,P.likes,P.comments,P.follows,P.verified,P.views,P.isAdmin,P.isModerator,P.moderators,P.moderatorsError]);syncAdminNav();updateAccount();const status=document.getElementById('sync-status');if(status)status.textContent='Лента обновляется автоматически';if(before!==after||!document.querySelector('[data-content-ready]'))safeDraw();}catch(err){console.error(err);let status=document.getElementById('sync-status');if(status)status.textContent='Нет связи с базой. Повторим автоматически.';if(!P.loaded){let m=document.getElementById('main');if(m)m.innerHTML=`<div class="error">Не удалось загрузить данные: ${esc(err.message)}</div><button class="quiet" id="retry">Повторить</button>`;document.getElementById('retry')?.addEventListener('click',load)}else toast('Нет связи с базой — повторим автоматически.')}}
function safeDraw(){let active=document.activeElement;if(active&&document.getElementById('main')?.contains(active)&&['INPUT','TEXTAREA'].includes(active.tagName)){P.renderDeferred=true;active.addEventListener('blur',()=>{if(P.renderDeferred){P.renderDeferred=false;draw()}},{once:true});return}draw()}
function scheduleLoad(ms=700){clearTimeout(P.refreshTimer);P.refreshTimer=setTimeout(load,ms)}
async function activityPing(){if(!P.client||!P.session||document.visibilityState!=='visible'||Date.now()-P.heartbeatAt<60000)return;P.heartbeatAt=Date.now();try{check(await P.client.rpc('pear_heartbeat'));if(P.page==='admin')await refreshAdminStats()}catch(e){console.warn('Activity update unavailable')}}
async function refreshAdminStats(){if(!P.isAdmin||P.page!=='admin')return;try{const data=check(await P.client.rpc('pear_admin_stats'));if(P.page!=='admin'||!P.isAdmin)return;P.stats=data;renderAdminStats()}catch(e){if(P.page==='admin'){P.stats=null;renderAdminStats()}}}
function renderAdminStats(){const el=document.getElementById('admin-stats');if(!el)return;const data=P.stats;if(!data){el.innerHTML='<p class="hint">Статистика пока недоступна. Проверь настройку базы.</p>';return}const entries=[['Онлайн',data.online],['Пользователей',data.users],['Публикаций',data.posts],['Новых за 24 часа',data.new_users_24h],['С галочкой',data.verified]];el.innerHTML=entries.map(([label,value])=>`<div class="stat-card"><span>${esc(label)}</span><strong>${Number.isFinite(Number(value))?Number(value):'—'}</strong></div>`).join('')+'<p class="stats-note">Онлайн — активные за последние 5 минут; показатель приблизительный.</p>'}
function startRealtime(){if(P.realtime)P.client.removeChannel(P.realtime);let c=P.client.channel('pear-changes');for(const table of ['posts','likes','comments','follows','profiles','pear_verified_profiles'])c=c.on('postgres_changes',{event:'*',schema:'public',table},()=>scheduleLoad(500));P.realtime=c.subscribe();P.heartbeatAt=0;activityPing();Chats.start();Notifications.start();clearInterval(P.interval);P.interval=setInterval(()=>{if(document.visibilityState==='visible'){load();activityPing();if(P.page==='admin')refreshReports()}},25000)}
function mutateStart(){P.pending++;P.revision++;P.fetchSeq++}function mutateEnd(){P.pending--;scheduleLoad(300)}
function postsForView(){let posts=[...P.posts];if(P.page==='post')posts=P.detailPost?[P.detailPost]:[];if(P.page==='profile'){posts=posts.filter(p=>p.author_id===P.profileId);const pin=P.pins.find(x=>x.author_id===P.profileId);if(pin?.posts&&!posts.some(p=>p.id===pin.post_id))posts.push(pin.posts);if(pin)posts.sort((a,b)=>(b.id===pin.post_id?1:0)-(a.id===pin.post_id?1:0))}if(P.page==='feed'&&P.tab==='following'){let followed=new Set(P.follows.filter(x=>x.follower_id===P.session.user.id).map(x=>x.following_id));posts=posts.filter(p=>followed.has(p.author_id))}if(P.page==='feed'&&P.tab==='trends')posts.sort((a,b)=>P.likes.filter(x=>x.post_id===b.id).length-P.likes.filter(x=>x.post_id===a.id).length);if(P.page==='search'){let q=P.query.toLowerCase();posts=q?posts.filter(p=>(p.body+' '+nameOf(p.author_id).display_name+' '+nameOf(p.author_id).username).toLowerCase().includes(q)):[]}return posts}
function likeMarkup(post){const mine=P.likes.some(l=>l.post_id===post.id&&l.user_id===P.session.user.id),n=P.likes.filter(l=>l.post_id===post.id).length;return `<button class="act ${mine?'liked':''}" data-like="${esc(post.id)}" aria-pressed="${mine}" aria-label="${mine?'Убрать лайк':'Поставить лайк'}">${icon('heart')} <span>${n}</span></button>`}
function commentHTML(c,comments){const a=nameOf(c.author_id),parent=comments.find(x=>x.id===c.parent_id),target=parent?nameOf(parent.author_id):null;return `<div class="comment ${parent?'comment-reply':''}" id="comment-${esc(c.id)}">${avatar(a)}<div class="comment-content"><button class="user-btn" data-profile="${esc(a.id)}">${esc(a.display_name)}</button>${badge(a.id)}<span class="post-meta"> · ${esc(date(c.created_at))}</span>${target?`<div class="reply-label">В ответ @${esc(target.username)}</div>`:''}<div class="comment-text">${formatBody(c.body)}</div><button type="button" class="reply-action" data-reply-comment="${esc(c.id)}" data-reply-post="${esc(c.post_id)}">Ответить</button></div></div>`}
function postHTML(p){const a=nameOf(p.author_id),comments=P.comments.filter(c=>c.post_id===p.id);let img=p.media_path?P.client.storage.from('post-media').getPublicUrl(p.media_path).data.publicUrl:'';return `<article class="card" data-post="${esc(p.id)}"><div class="post-head">${avatar(a)}<div class="grow"><button class="user-btn" data-profile="${esc(a.id)}">${esc(a.display_name)}</button>${badge(a.id)}<div class="post-meta">@${esc(a.username)} · ${esc(date(p.created_at))}</div></div><span class="tag">${esc(p.category)}</span><button type="button" class="post-more" data-post-menu="${esc(p.id)}" aria-label="Действия с публикацией" title="Действия с публикацией">${icon('more')}</button></div>${P.page==='profile'&&P.profileId===p.author_id&&P.pins.some(x=>x.post_id===p.id)?'<div class="pinned-label">'+icon('pin')+' Закреплено в профиле</div>':''}${p.body?`<div class="body">${formatBody(p.body)}</div>`:''}${img?`<img class="post-image" src="${esc(img)}" alt="Изображение к публикации" loading="lazy" decoding="async">`:''}<div class="post-actions">${likeMarkup(p)}<button class="act" data-comments="${esc(p.id)}" aria-expanded="${P.expanded.has(p.id)}">${icon('comment')} ${comments.length}</button><span class="view-stat" aria-label="Просмотры" title="Уникальные просмотры">${icon('eye')} <span data-view-count="${esc(p.id)}">${Number(P.views.find(v=>v.post_id===p.id)?.total||0)}</span></span></div>${P.expanded.has(p.id)?`<div class="comments">${comments.map(c=>commentHTML(c,comments)).join('')}${P.replyTargets[p.id]?`<div class="replying-to"><span>Ответ для <strong>@${esc(nameOf(comments.find(c=>c.id===P.replyTargets[p.id])?.author_id).username)}</strong></span><button type="button" data-cancel-reply="${esc(p.id)}" aria-label="Отменить ответ">×</button></div>`:''}<form class="comment-form" data-comment-form="${esc(p.id)}"><input class="field" name="body" maxlength="500" required placeholder="Написать комментарий..." aria-label="Текст комментария"><button class="primary">Отправить</button></form></div>`:''}</article>`}
function list(posts,empty){return posts.length?posts.map(postHTML).join(''):`<div class="empty">${esc(empty)}</div>`}
function verifiedRecommendations(){const verifiedIds=new Set(P.verified.map(v=>v.profile_id));const users=P.profiles.filter(a=>a.id!==P.session.user.id&&verifiedIds.has(a.id)).sort((a,b)=>a.display_name.localeCompare(b.display_name,'ru')).slice(0,6);return `<div class="section-line"><h2>Рекомендации</h2><span>Подтверждённые пользователи</span></div>`+(users.length?`<div class="recommendations">${users.map(a=>`<div class="card recommendation">${avatar(a)}<div class="grow"><button class="user-btn" data-profile="${esc(a.id)}">${esc(a.display_name)}</button>${badge(a.id)}<div class="post-meta">@${esc(a.username)}</div></div><button class="quiet" data-profile="${esc(a.id)}">Профиль</button></div>`).join('')}</div>`:'<div class="empty">Подтверждённых пользователей пока нет.</div>')}
function draw(){const main=document.getElementById('main');if(!main||!P.loaded)return;if(P.page==='chat'){Chats.render();return}let posts=postsForView(),html='';if(P.page==='feed'){html=`<header class="topline"><div><h1>Твоя лента</h1><p>Место, где интересно быть собой.</p></div></header><div class="tabs"><button class="tab ${P.tab==='new'?'active':''}" data-tab="new">Новое</button><button class="tab ${P.tab==='trends'?'active':''}" data-tab="trends">Тренды</button><button class="tab ${P.tab==='following'?'active':''}" data-tab="following">Подписки</button></div><div class="composer-mini">${avatar(P.me)}<button class="composer-trigger" data-compose>Что у тебя нового?</button><button class="primary" data-compose>Написать пост</button></div><div class="section-line"><h2>Публикации</h2><span>Делись моментами</span></div>`+list(posts,P.tab==='following'?'Пока нет постов от подписок. Найди людей через поиск.':'Здесь пока тихо. Напиши первый пост!')}else if(P.page==='profile'){const a=nameOf(P.profileId),mine=P.profileId===P.session.user.id,following=P.follows.some(f=>f.follower_id===P.session.user.id&&f.following_id===P.profileId),f=P.follows.filter(x=>x.following_id===P.profileId).length,g=P.follows.filter(x=>x.follower_id===P.profileId).length;html=`<div class="profile-cover">${a.banner_path?`<img class="profile-cover-image" src="${esc(mediaUrl(a.banner_path))}" alt="Баннер профиля">`:''}</div><div class="profile-box">${avatar(a)}<div class="row"><div class="grow"><h1>${esc(a.display_name)} ${badge(a.id)}</h1><span class="post-meta">@${esc(a.username)}</span>${badgeType(a.id)==='moderator'?'<div class="profile-developer profile-moderator">Модератор проекта Pear</div>':badgeType(a.id)==='green'?'<div class="profile-developer">Разработчик проекта Pear</div>':''}</div>${mine?'':`<button class="quiet profile-message" data-message-user="${esc(a.id)}">Написать сообщение</button>`}<button class="quiet" data-profile-action>${mine?'Редактировать профиль':following?'Отписаться':'Подписаться'}</button></div><p>${esc(a.bio||'Пока ничего о себе не рассказал(а).')}</p><div class="row post-meta"><span><strong>${f}</strong> подписчиков</span><span><strong>${g}</strong> подписок</span></div></div><div class="section-line"><h2>Публикации</h2><span>${posts.length} в ленте</span></div>`+list(posts,'Здесь пока нет публикаций.')}else if(P.page==='admin'){html=adminHTML()}else if(P.page==='notifications'){html=Notifications.html()}else if(P.page==='post'){html=`<header class="topline"><div><h1>Публикация</h1><p>Обсуждение Pear</p></div></header>`+list(posts,'Публикация не найдена или загружается.')}else{let q=P.query.toLowerCase(),people=q?P.profiles.filter(p=>(p.display_name+' '+p.username).toLowerCase().includes(q.replace(/^@/,''))):[];html=`<header class="topline"><div><h1>Поиск</h1><p>Люди и публикации в Pear.</p></div></header><form id="search-form" class="row"><input id="q" class="search grow" name="q" value="${esc(P.query)}" placeholder="Имя, ник или текст поста" aria-label="Поисковый запрос"><button class="primary">Найти</button></form>`+(q?`<div class="section-line"><h2>Люди</h2><span>${people.length} найдено</span></div>${people.length?people.map(a=>`<div class="card row">${avatar(a)}<div><button class="user-btn" data-profile="${esc(a.id)}">${esc(a.display_name)}</button>${badge(a.id)}<div class="post-meta">@${esc(a.username)}</div></div></div>`).join(''):'<div class="empty">Пользователи не найдены</div>'}<div class="section-line"><h2>Публикации</h2><span>${posts.length} найдено</span></div>${list(posts,'Публикации не найдены')}`:verifiedRecommendations())}const tpl=document.createElement('template');tpl.innerHTML=html;let host=main.querySelector('[data-content-ready]');if(!host){main.innerHTML='<div data-content-ready></div>';host=main.firstElementChild}const desired=[...tpl.content.children],ids=new Set(desired.filter(n=>n.dataset.post).map(n=>n.dataset.post));[...host.children].filter(n=>n.dataset.post&&!ids.has(n.dataset.post)).forEach(n=>n.remove());desired.forEach((n,i)=>{let target=host.children[i],existing=n.dataset.post?[...host.children].find(x=>x.dataset.post===n.dataset.post):null;if(existing){if(existing.outerHTML!==n.outerHTML){existing.replaceWith(n);existing=n}if(host.children[i]!==existing)host.insertBefore(existing,host.children[i]||null)}else if(target&&!target.dataset.post){if(target.outerHTML!==n.outerHTML)target.replaceWith(n)}else host.insertBefore(n,target||null)});while(host.children.length>desired.length)host.lastElementChild.remove();bind(main);if(P.page==='notifications')Notifications.bind(main);if(P.page==='admin'){if(P.stats)renderAdminStats();renderReports()}observeViews()}
function bind(main){main.querySelectorAll('[data-reply-comment]').forEach(b=>b.onclick=()=>{P.replyTargets[b.dataset.replyPost]=b.dataset.replyComment;const y=scrollY;draw();scrollTo(0,y);document.querySelector(`[data-comment-form="${CSS.escape(b.dataset.replyPost)}"] input`)?.focus()});main.querySelectorAll('[data-cancel-reply]').forEach(b=>b.onclick=()=>{delete P.replyTargets[b.dataset.cancelReply];const y=scrollY;draw();scrollTo(0,y)});main.querySelectorAll('[data-post-menu]').forEach(b=>b.onclick=()=>openPostMenu(b.dataset.postMenu));main.querySelectorAll('[data-report-status]').forEach(b=>b.onclick=()=>resolveReport(b));main.querySelectorAll('[data-message-user]').forEach(b=>b.onclick=()=>Chats.openUser(b.dataset.messageUser));main.querySelectorAll('[data-hashtag]').forEach(b=>b.onclick=()=>{P.query=b.dataset.hashtag;P.page='search';saveLocation();updateNav();draw();Chats.onNavigate();window.scrollTo(0,0)});main.querySelectorAll('[data-mention]').forEach(b=>b.onclick=()=>{P.query=b.dataset.mention;P.page='search';saveLocation();updateNav();draw();Chats.onNavigate();window.scrollTo(0,0)});const admform=main.querySelector('#admin-search');if(admform)admform.onsubmit=ev=>{ev.preventDefault();P.adminQuery=admform.elements.q.value.trim();saveLocation();draw()};main.querySelectorAll('[data-verify]').forEach(b=>b.onclick=()=>setVerified(b));main.querySelectorAll('[data-moderator]').forEach(b=>b.onclick=()=>setModerator(b));main.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>navigate('profile',b.dataset.profile));main.querySelectorAll('[data-compose]').forEach(b=>b.onclick=compose);main.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{P.tab=b.dataset.tab;saveLocation();draw()});const sf=main.querySelector('#search-form');if(sf)sf.onsubmit=ev=>{ev.preventDefault();P.query=ev.currentTarget.elements.q.value.trim();saveLocation();draw()};const pa=main.querySelector('[data-profile-action]');if(pa)pa.onclick=()=>P.profileId===P.session.user.id?editProfile():toggleFollow();main.querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>toggleLike(b));main.querySelectorAll('[data-comments]').forEach(b=>b.onclick=()=>{P.expanded.has(b.dataset.comments)?P.expanded.delete(b.dataset.comments):P.expanded.add(b.dataset.comments);const y=scrollY;draw();window.scrollTo(0,y)});main.querySelectorAll('[data-comment-form]').forEach(form=>form.onsubmit=postComment);main.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deletePost(b.dataset.delete))}
async function toggleLike(button){if(button.dataset.pending)return;const id=button.dataset.like,uid=P.session.user.id,liked=P.likes.some(x=>x.post_id===id&&x.user_id===uid);button.dataset.pending='1';mutateStart();if(liked)P.likes=P.likes.filter(x=>!(x.post_id===id&&x.user_id===uid));else P.likes.push({post_id:id,user_id:uid});updateLike(button,id);try{if(liked)check(await P.client.from('likes').delete().eq('post_id',id).eq('user_id',uid));else check(await P.client.from('likes').insert({post_id:id,user_id:uid}))}catch(err){if(liked)P.likes.push({post_id:id,user_id:uid});else P.likes=P.likes.filter(x=>!(x.post_id===id&&x.user_id===uid));updateLike(button,id);toast('Не удалось сохранить лайк: '+err.message)}finally{delete button.dataset.pending;mutateEnd()}}
function updateLike(button,id){const liked=P.likes.some(l=>l.post_id===id&&l.user_id===P.session.user.id);button.classList.toggle('liked',liked);button.setAttribute('aria-pressed',String(liked));button.setAttribute('aria-label',liked?'Убрать лайк':'Поставить лайк');button.querySelector('span').textContent=P.likes.filter(l=>l.post_id===id).length;button.classList.remove('pop');void button.offsetWidth;button.classList.add('pop')}
async function postComment(ev){ev.preventDefault();const form=ev.currentTarget,input=form.elements.body,body=input.value.trim();if(!body)return;const button=form.querySelector('button');button.disabled=true;mutateStart();try{const row=check(await P.client.from('comments').insert({post_id:form.dataset.commentForm,author_id:P.session.user.id,body,parent_id:P.replyTargets[form.dataset.commentForm]||null}).select().single());P.comments.push(row);delete P.replyTargets[form.dataset.commentForm];const y=scrollY;draw();scrollTo(0,y)}catch(err){toast('Не удалось отправить комментарий: '+err.message);button.disabled=false}finally{mutateEnd()}}
async function deletePost(id){if(!confirm('Удалить этот пост?'))return;let post=findPost(id);if(!post)return;mutateStart();try{check(await P.client.from('posts').delete().eq('id',id).eq('author_id',P.session.user.id));P.posts=P.posts.filter(p=>p.id!==id);P.pins=P.pins.filter(p=>p.post_id!==id);document.querySelector(`[data-post="${CSS.escape(id)}"]`)?.remove();if(post.media_path){let {error:err}=await P.client.storage.from('post-media').remove([post.media_path]);if(err)toast('Пост удалён, но файл остался в хранилище.')}if(!postsForView().length)draw()}catch(err){toast('Не удалось удалить: '+err.message)}finally{mutateEnd()}}

function findPost(id){return P.posts.find(p=>p.id===id)||P.pins.find(x=>x.post_id===id)?.posts||(P.detailPost?.id===id?P.detailPost:null)}
function openPostMenu(id){
 const post=findPost(id);if(!post)return;const mine=post.author_id===P.session.user.id,pinned=P.pins.some(x=>x.post_id===id);
 const modal=dialog('Действия с публикацией',`<div class="post-menu-intro">${mine?'Управляй своей публикацией':'Помоги сделать Pear безопаснее'}</div><div class="post-menu-list">${mine?`<button type="button" class="post-menu-action" data-action="pin"><span class="menu-icon">${icon('pin')}</span><span><strong>${pinned?'Открепить от профиля':'Закрепить в профиле'}</strong><small>${pinned?'Убрать публикацию из закреплённых':'Показывать первой в твоём профиле'}</small></span></button><button type="button" class="post-menu-action is-danger" data-action="delete"><span class="menu-icon">×</span><span><strong>Удалить публикацию</strong><small>Это действие нельзя отменить</small></span></button>`:`<button type="button" class="post-menu-action is-danger" data-action="report"><span class="menu-icon">!</span><span><strong>Пожаловаться</strong><small>Сообщить администраторам о нарушении</small></span></button>`}</div>`);
 modal.querySelector('[data-action=pin]')?.addEventListener('click',()=>{modal.remove();togglePin(post,pinned)});
 modal.querySelector('[data-action=delete]')?.addEventListener('click',()=>{modal.remove();deletePost(id)});
 modal.querySelector('[data-action=report]')?.addEventListener('click',()=>reportDialog(post));
}
async function togglePin(post,pinned){
 if(post.author_id!==P.session.user.id)return;mutateStart();try{check(await P.client.rpc('pear_set_pinned_post',{p_post_id:pinned?null:post.id}));P.pins=P.pins.filter(x=>x.author_id!==post.author_id);if(!pinned)P.pins.push({author_id:post.author_id,post_id:post.id,posts:post});draw();toast(pinned?'Публикация откреплена':'Публикация закреплена в профиле')}catch(e){toast('Не удалось изменить закрепление. Проверьте обновление базы.')}finally{mutateEnd()}
}
function reportDialog(post){
 const m=dialog('Пожаловаться на публикацию',`<p class="report-intro">Расскажи, что не так. Жалобу увидят администраторы и модераторы Pear.</p><form id="report-form"><label class="label">Причина<select class="field" name="reason" required><option value="">Выбери причину</option><option>Спам</option><option>Оскорбления или травля</option><option>Неприемлемый контент</option><option>Мошенничество</option><option>Другое</option></select></label><label class="label">Комментарий — необязательно<textarea class="field report-details" name="details" maxlength="500" placeholder="Добавь подробности"></textarea></label><button class="primary report-submit" type="submit">Отправить жалобу</button></form>`);
 m.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget,button=form.querySelector('button'),reason=form.elements.reason.value,details=form.elements.details.value.trim();if(!reason)return;button.disabled=true;button.textContent='Отправляем…';try{check(await P.client.rpc('pear_report_post',{p_post_id:post.id,p_reason:reason,p_details:details}));m.remove();toast('Жалоба отправлена на рассмотрение')}catch(e){error(e.code==='23505'?'Ты уже жаловался на эту публикацию.':'Не удалось отправить жалобу. Проверьте обновление базы.');button.disabled=false;button.textContent='Отправить жалобу'}};
}
async function refreshReports(){
 if((!P.isAdmin&&!P.isModerator)||P.page!=='admin'||!P.session)return;const uid=P.session.user.id;
 try{const [reportResult,cleanupResult]=await Promise.all([P.client.from('pear_post_reports').select('id,reporter_id,post_id,reason,details,status,created_at,posts(id,author_id,body,media_path)').order('created_at',{ascending:false}).limit(100),P.client.from('pear_moderation_media_cleanup').select('id,media_path,created_at').order('created_at',{ascending:false}).limit(100)]);const result=check(reportResult);if((!P.isAdmin&&!P.isModerator)||P.page!=='admin'||P.session?.user.id!==uid)return;P.reports=result||[];P.reportsLoaded=true;P.reportsError=false;P.cleanupError=!!cleanupResult.error;P.mediaCleanup=cleanupResult.error?[]:(cleanupResult.data||[]);renderReports()}
 catch(e){if(P.page==='admin'&&P.session?.user.id===uid){P.reportsError=true;renderReports()}}
}
function renderReports(){
 const box=document.getElementById('admin-reports');if(!box)return;if(P.reportsError){box.innerHTML='<div class="reports-empty">Не удалось загрузить жалобы. Проверь обновление базы.</div>';return}if(!P.reportsLoaded){box.innerHTML='<div class="reports-empty">Загружаем жалобы…</div>';return}
 const reports=P.reports;box.innerHTML=reports.length?reports.map(r=>{const author=nameOf(r.posts?.author_id),reporter=nameOf(r.reporter_id),open=r.status==='open',image=r.posts?.media_path?P.client.storage.from('post-media').getPublicUrl(r.posts.media_path).data.publicUrl:'';return `<article class="report-card"><div class="report-card-head"><span class="report-reason">${esc(r.reason)}</span><span class="report-state ${open?'is-open':''}">${open?'Новая':'Рассмотрена'}</span></div><p class="report-post">${esc(r.posts?.body||'Публикация с изображением')}</p>${image?`<a class="report-media" href="${esc(image)}" target="_blank" rel="noopener noreferrer">Открыть изображение ↗</a>`:''}${r.details?`<div class="report-note"><span>Комментарий</span>${esc(r.details)}</div>`:''}<div class="report-meta">Автор: @${esc(author.username)} · Жалоба от: @${esc(reporter.username)} · ${esc(date(r.created_at))}</div>${open?`<button type="button" class="quiet report-resolve" data-report-status="${esc(r.id)}">Отметить рассмотренной</button>`:`<button type="button" class="report-delete" data-report-delete="${esc(r.id)}">Удалить публикацию</button>`}</article>`}).join(''):'<div class="reports-empty">Пока нет жалоб на публикации.</div>';
 if(P.mediaCleanup.length)box.insertAdjacentHTML('beforeend',`<div class="cleanup-notice"><strong>Осталось удалить файлов: ${P.mediaCleanup.length}</strong><p>Публикации уже удалены, но некоторые изображения остались в хранилище.</p><button type="button" class="quiet" data-cleanup-retry>Повторить очистку</button></div>`);
 box.querySelectorAll('[data-report-status]').forEach(b=>b.onclick=()=>resolveReport(b));box.querySelectorAll('[data-report-delete]').forEach(b=>b.onclick=()=>confirmAdminDelete(b.dataset.reportDelete));box.querySelector('[data-cleanup-retry]')?.addEventListener('click',retryMediaCleanup);
}
async function resolveReport(button){
 if(!P.isAdmin&&!P.isModerator)return;button.disabled=true;try{check(await P.client.rpc('pear_resolve_post_report',{p_report_id:button.dataset.reportStatus}));await refreshReports();toast('Жалоба отмечена рассмотренной')}catch(e){button.disabled=false;toast('Не удалось обновить жалобу')}
}

async function toggleFollow(){const id=P.profileId,uid=P.session.user.id,followed=P.follows.some(f=>f.follower_id===uid&&f.following_id===id);mutateStart();try{if(followed)check(await P.client.from('follows').delete().eq('follower_id',uid).eq('following_id',id));else check(await P.client.from('follows').insert({follower_id:uid,following_id:id}));if(followed)P.follows=P.follows.filter(f=>!(f.follower_id===uid&&f.following_id===id));else P.follows.push({follower_id:uid,following_id:id});draw()}catch(err){toast('Не удалось изменить подписку: '+err.message)}finally{mutateEnd()}}
function setupProfileSignOut(modal){
 const show=modal.querySelector('#sign-out'),panel=modal.querySelector('.signout-confirm'),cancel=panel.querySelector('[data-cancel-signout]'),confirm=panel.querySelector('[data-confirm-signout]');
 show.onclick=()=>{panel.hidden=false;show.setAttribute('aria-expanded','true');cancel.focus();panel.scrollIntoView({block:'nearest',behavior:'smooth'})};
 cancel.onclick=()=>{panel.hidden=true;show.setAttribute('aria-expanded','false');show.focus()};
 confirm.onclick=async()=>{confirm.disabled=true;cancel.disabled=true;confirm.textContent='Выходим…';try{const {error:err}=await P.client.auth.signOut({scope:'local'});if(err)throw err;resetProfileTaps();modal.remove()}catch(err){error('Не удалось выйти из аккаунта. Попробуй ещё раз.');confirm.disabled=false;cancel.disabled=false;confirm.textContent='Выйти'}};
}
function editProfile(){const a=nameOf(P.session.user.id);const m=dialog('Редактировать профиль',`<form id="edit"><label class="label">Имя<input class="field" name="display_name" maxlength="60" value="${esc(a.display_name)}" required></label><label class="label">Ник — латинские буквы, цифры и _<input class="field" name="username" value="${esc(a.username)}" pattern="[a-zA-Z0-9_]{3,24}" minlength="3" maxlength="24" required></label><label class="label">О себе<textarea class="field" name="bio" maxlength="240">${esc(a.bio)}</textarea></label><label class="label">Аватарка — JPG, PNG, WebP или GIF до 5 МБ<input class="field" type="file" name="avatar" accept="image/jpeg,image/png,image/webp,image/gif"></label><label class="label">Баннер — JPG, PNG, WebP или GIF до 5 МБ<input class="field" type="file" name="banner" accept="image/jpeg,image/png,image/webp,image/gif"></label><p class="hint">Изображения публичны: их могут открыть по прямой ссылке.</p><button class="primary">Сохранить</button></form><div class="account-actions"><div class="account-actions-heading"><strong>Аккаунт</strong><span>Управление сессией и профилем</span></div><div class="account-action-buttons"><button type="button" class="quiet account-signout" id="sign-out">${icon('logout')} Выйти из аккаунта</button><button type="button" class="danger-button" id="delete-account">Удалить аккаунт</button></div><p class="account-action-note">Выход не удалит твой аккаунт. Удаление необратимо.</p><div class="signout-confirm" hidden><p>Выйти на этом устройстве? Несохранённые изменения профиля будут потеряны.</p><div class="signout-confirm-actions"><button type="button" class="quiet" data-cancel-signout>Отмена</button><button type="button" class="primary" data-confirm-signout>Выйти</button></div></div></div>`);m.querySelector('#delete-account').onclick=deleteAccountDialog;setupProfileSignOut(m);m.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget,display_name=f.elements.display_name.value.trim(),username=f.elements.username.value.trim(),bio=f.elements.bio.value.trim(),avatarFile=f.elements.avatar.files[0],bannerFile=f.elements.banner.files[0];if(!display_name)return error('Укажи имя.');for(const file of [avatarFile,bannerFile])if(file&&(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)||file.size>5242880))return error('Выбери изображение JPG, PNG, WebP или GIF до 5 МБ.');const btn=f.querySelector('button');btn.disabled=true;btn.textContent='Сохраняем…';let uploads=[],avatar_path=a.avatar_path||null,banner_path=a.banner_path||null,old=[];mutateStart();try{for(const [kind,file] of [['avatar',avatarFile],['banner',bannerFile]]){if(!file)continue;const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'}[file.type],path=P.session.user.id+'/'+kind+'-'+crypto.randomUUID()+'.'+ext;check(await P.client.storage.from('profile-media').upload(path,file,{contentType:file.type,upsert:false}));uploads.push(path);if(kind==='avatar'){if(avatar_path)old.push(avatar_path);avatar_path=path}else{if(banner_path)old.push(banner_path);banner_path=path}}check(await P.client.from('profiles').update({display_name,username,bio,avatar_path,banner_path}).eq('id',P.session.user.id));Object.assign(a,{display_name,username,bio,avatar_path,banner_path});P.me=a;m.remove();updateAccount();draw();toast('Профиль сохранён');if(old.length){const {error:cleanupError}=await P.client.storage.from('profile-media').remove(old);if(cleanupError)toast('Профиль сохранён, но старый файл остался в Storage.')}}catch(err){if(uploads.length)await P.client.storage.from('profile-media').remove(uploads);error('Не удалось сохранить: '+err.message);btn.disabled=false;btn.textContent='Сохранить'}finally{mutateEnd()}}}

function deleteAccountDialog(){const modal=dialog('Удалить аккаунт?',`<div class="delete-warning"><p>Аккаунт, профиль, публикации, комментарии, лайки, подписки и файлы в папках Pear будут удалены. Это нельзя отменить.</p><p>Введите <strong>УДАЛИТЬ</strong> для подтверждения.</p><label class="label" for="confirm-delete">Подтверждение</label><input class="field" id="confirm-delete" autocomplete="off" placeholder="УДАЛИТЬ"><button type="button" class="danger-button" id="confirm-delete-button" disabled>Удалить навсегда</button></div>`);const input=modal.querySelector('#confirm-delete'),button=modal.querySelector('#confirm-delete-button');input.oninput=()=>button.disabled=input.value.trim()!=='УДАЛИТЬ';button.onclick=async()=>{if(input.value.trim()!=='УДАЛИТЬ')return;button.disabled=true;button.textContent='Удаляем…';try{const result=await P.client.auth.getSession();const token=result?.data?.session?.access_token;if(!token)throw Error('Войдите в аккаунт заново.');const r=await fetch('/api/delete-account',{method:'POST',headers:{Authorization:'Bearer '+token},cache:'no-store'});let data;try{data=await r.json()}catch{throw Error('Сервер удаления недоступен.')}if(!r.ok||!data.ok)throw Error(data.error||'Не удалось удалить аккаунт.');await P.client.auth.signOut({scope:'local'});location.reload()}catch(e){error(e.message||'Не удалось удалить аккаунт.');button.disabled=false;button.textContent='Удалить навсегда'}}}
function compose(){let url;const modal=dialog('Новая публикация',`<form id="compose"><textarea class="field" name="body" maxlength="1000" placeholder="Поделись мыслями..." aria-label="Текст публикации"></textarea><div class="suggestions" hidden></div><p class="hint mention-hint">Для упоминания набери @, для темы — #</p><label class="label">Категория<select class="field" name="category"><option>Общее</option><option>Игры</option><option>Технологии</option><option>Творчество</option></select></label><label class="label">Изображение или GIF, до 5 МБ<input class="field" type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif"></label><img class="preview" alt="Предпросмотр" hidden><div class="row"><span class="hint grow">До 1000 символов</span><button class="primary" type="submit">Опубликовать</button></div></form>`);setupSuggestions(modal);const file=modal.querySelector('[name=image]'),preview=modal.querySelector('.preview');file.onchange=()=>{if(url)URL.revokeObjectURL(url);if(file.files[0]){url=URL.createObjectURL(file.files[0]);preview.src=url;preview.hidden=false}else preview.hidden=true};modal.querySelector('form').onsubmit=async ev=>{ev.preventDefault();let f=ev.currentTarget,body=f.elements.body.value.trim(),image=file.files[0];if(!body&&!image)return error('Добавь текст или изображение.');if(image&&(!['image/jpeg','image/png','image/webp','image/gif'].includes(image.type)||image.size>5242880))return error('Выбери JPG, PNG, WebP или GIF до 5 МБ.');const button=f.querySelector('[type=submit]');button.disabled=true;button.textContent='Публикуем…';let path=null;mutateStart();try{if(image){let ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'}[image.type];path=P.session.user.id+'/'+crypto.randomUUID()+'.'+ext;check(await P.client.storage.from('post-media').upload(path,image,{contentType:image.type,upsert:false}))}let post=check(await P.client.from('posts').insert({author_id:P.session.user.id,body,category:f.elements.category.value,media_path:path}).select().single());P.posts.unshift(post);if(url)URL.revokeObjectURL(url);modal.remove();P.page='feed';P.tab='new';updateNav();draw();window.scrollTo({top:0,behavior:'smooth'});toast('Публикация добавлена')}catch(err){if(path)await P.client.storage.from('post-media').remove([path]);error('Не удалось опубликовать: '+err.message);button.disabled=false;button.textContent='Опубликовать'}finally{mutateEnd()}}}
function adminHTML(){
 if(!P.isAdmin&&!P.isModerator)return '<div class="error">Доступ к панели запрещён.</div>';
 const reports=`<div class="section-line reports-heading"><h2>Жалобы на публикации</h2><span>Администраторы и модераторы</span></div><section id="admin-reports" aria-label="Жалобы на публикации"></section>`;
 if(!P.isAdmin)return `<header class="topline"><div><h1>Панель модератора</h1><p>Жалобы и безопасность Pear</p></div></header><div class="admin-intro"><span class="admin-mark">${icon('shield')}</span><div><strong>Модерация публикаций</strong><p class="hint">Просматривай жалобы, отмечай рассмотренные и при необходимости удаляй публикации.</p></div></div>${reports}`;
 const q=P.adminQuery.toLowerCase().replace(/^@/,'');const people=P.profiles.filter(x=>(x.display_name+' '+x.username).toLowerCase().includes(q));
 return `<header class="topline"><div><h1>Админ-панель</h1><p>Управление сообществом Pear</p></div></header><div class="admin-intro"><span class="admin-mark">${icon('shield')}</span><div><strong>Команда Pear</strong><p class="hint">Назначай модераторов, управляй галочками и рассматривай жалобы.</p></div></div><div class="section-line"><h2>Статистика</h2></div><section id="admin-stats" class="admin-stats" aria-label="Статистика сайта"><p class="hint">Загружаем статистику…</p></section>${reports}<form class="row admin-search" id="admin-search"><input class="search grow" name="q" placeholder="Найти по имени или нику" value="${esc(P.adminQuery)}" aria-label="Поиск пользователей"><button class="primary">Найти</button></form><div class="section-line"><h2>Пользователи</h2><span>${people.length} найдено</span></div><p class="mod-help">Назначение автоматически добавляет значок и подпись модератора. Прежняя верификация вернётся после снятия роли.</p>${P.moderatorsError?'<div class="reports-empty">Не удалось загрузить роли. Проверь обновление базы.</div>':''}${people.length?people.map(a=>{const on=P.verified.some(v=>v.profile_id===a.id),mod=P.moderators.some(m=>m.user_id===a.id);return `<div class="card admin-row mod-user-row">${avatar(a)}<div class="grow"><button class="user-btn" data-profile="${esc(a.id)}">${esc(a.display_name)}</button>${badge(a.id)}<div class="post-meta">@${esc(a.username)} ${mod?' · Модератор':''}</div></div><div class="mod-user-actions"><button type="button" class="quiet verify-action ${on?'is-verified':''}" data-verify="${esc(a.id)}" aria-label="${on?'Изменить галочку':'Выдать галочку'} ${esc(a.username)}">${on?'Галочка':'Выдать галочку'}</button><button type="button" class="quiet mod-role-button ${mod?'is-mod':''}" data-moderator="${esc(a.id)}" ${P.moderatorsError?'disabled':''}>${mod?'Снять модератора':'Назначить модератором'}</button></div></div>`}).join(''):'<div class="empty">Пользователи не найдены.</div>'}`;
}
function setModerator(button){
 if(!P.isAdmin||P.moderatorsError)return;
 const id=button.dataset.moderator,person=nameOf(id),enabled=P.moderators.some(m=>m.user_id===id),action=enabled?'Снять роль':'Назначить модератором';
 const m=dialog(action,`<p class="mod-dialog-text">${enabled?'Снять права модератора у':'Назначить модератором'} <strong>@${esc(person.username)}</strong>?</p><p class="hint">${enabled?'Пользователь потеряет доступ к жалобам и значок модератора.':'Модератор сможет просматривать жалобы и удалять публикации после рассмотрения жалобы. Назначать роли он не сможет.'}</p><div class="admin-delete-actions"><button type="button" class="quiet" data-cancel-role>Отмена</button><button type="button" class="${enabled?'danger-button':'primary'}" data-confirm-role>${action}</button></div>`);
 m.querySelector('[data-cancel-role]').onclick=()=>m.remove();m.querySelector('[data-confirm-role]').onclick=async ev=>{const b=ev.currentTarget;b.disabled=true;try{check(await P.client.rpc('pear_admin_set_moderator',{p_user_id:id,p_enabled:!enabled}));P.moderators=P.moderators.filter(x=>x.user_id!==id);if(!enabled)P.moderators.push({user_id:id});P.isModerator=P.moderators.some(x=>x.user_id===P.session.user.id);m.remove();syncAdminNav();draw();toast(enabled?'Роль модератора снята':'Модератор назначен')}catch(e){b.disabled=false;error('Не удалось изменить роль. Проверь права администратора и обновление базы.')}};
}
async function cleanupModeratedMedia(item){
 if(!item?.id||!item?.media_path)return;
 // If the file is absent or another post uses it, finish without deleting it.
 try{check(await P.client.rpc('pear_admin_finish_media_cleanup',{p_cleanup_id:item.id}));return}catch(_){/* The file may still need removal. */}
 const result=await P.client.storage.from('post-media').remove([item.media_path]);
 if(result.error)throw result.error;
 check(await P.client.rpc('pear_admin_finish_media_cleanup',{p_cleanup_id:item.id}));
}
async function retryMediaCleanup(ev){
 const button=ev.currentTarget;button.disabled=true;let failed=0;
 for(const item of P.mediaCleanup){try{await cleanupModeratedMedia(item)}catch(_){failed++}}
 await refreshReports();toast(failed?'Не все файлы удалось удалить. Повтори очистку.':'Очистка файлов завершена');
}
function confirmAdminDelete(reportId){
 if(!P.isAdmin&&!P.isModerator)return;const report=P.reports.find(r=>r.id===reportId&&r.status==='resolved');if(!report)return;
 const m=dialog('Удалить публикацию?',`<div class="admin-delete-warning"><p>Публикация будет удалена для всех пользователей. Связанные жалобы тоже удалятся. Это действие нельзя отменить.</p><div class="admin-delete-preview">${esc(report.posts?.body||'Публикация с изображением')}</div><div class="admin-delete-actions"><button type="button" class="quiet" data-cancel-delete>Отмена</button><button type="button" class="danger-button" data-confirm-delete>Удалить публикацию</button></div></div>`);
 m.querySelector('[data-cancel-delete]').onclick=()=>m.remove();m.querySelector('[data-confirm-delete]').onclick=async ev=>{
  const button=ev.currentTarget;button.disabled=true;button.textContent='Удаляем…';
  try{const result=check(await P.client.rpc('pear_admin_delete_reported_post',{p_report_id:reportId}));m.remove();P.posts=P.posts.filter(p=>p.id!==result.post_id);P.pins=P.pins.filter(p=>p.post_id!==result.post_id);let cleanupFailed=false;
   if(result.cleanup_id&&result.media_path){try{await cleanupModeratedMedia({id:result.cleanup_id,media_path:result.media_path})}catch(_){cleanupFailed=true}}
   await refreshReports();scheduleLoad(0);toast(cleanupFailed?'Пост удалён, но файл остался. Повтори очистку в админ-панели.':'Публикация удалена');
  }catch(e){error('Не удалось удалить публикацию. Проверь, что жалоба рассмотрена и обновление базы установлено.');button.disabled=false;button.textContent='Удалить публикацию'}
 };
}
function setVerified(button){
 if(!P.isAdmin)return;
 const id=button.dataset.verify, person=nameOf(id),current=P.verified.find(v=>v.profile_id===id)?.badge_type||null;
 const modal=dialog('Галочка профиля',`<p class="badge-choice-intro">Выбери галочку для <strong>@${esc(person.username)}</strong>. У профиля может быть только одна галочка.</p><div class="badge-choices"><button type="button" class="badge-choice" data-badge-choice="blue"><img src="/assets/verified.png" alt=""><span><strong>Синяя</strong><small>Подтверждённый профиль</small></span>${current==='blue'?'<span class="badge-current">Выбрана</span>':''}</button><button type="button" class="badge-choice" data-badge-choice="green"><img src="/assets/verified-green.png" alt=""><span><strong>Зелёная</strong><small>Разработчик проекта Pear</small></span>${current==='green'?'<span class="badge-current">Выбрана</span>':''}</button><button type="button" class="badge-choice badge-remove" data-badge-choice="none"><span><strong>Убрать галочку</strong><small>Без подтверждения</small></span>${!current?'<span class="badge-current">Выбрано</span>':''}</button></div>`);
 modal.querySelectorAll('[data-badge-choice]').forEach(option=>option.onclick=async()=>{
  const type=option.dataset.badgeChoice;if((current||'none')===type){modal.remove();return}
  modal.querySelectorAll('[data-badge-choice]').forEach(b=>b.disabled=true);mutateStart();
  try{check(await P.client.rpc('pear_set_verification',{p_profile_id:id,p_type:type}));P.verified=P.verified.filter(v=>v.profile_id!==id);if(type!=='none')P.verified.push({profile_id:id,badge_type:type});modal.remove();draw();toast(type==='none'?'Галочка убрана':'Галочка изменена')}
  catch(err){error('Не удалось изменить галочку: '+err.message);modal.querySelectorAll('[data-badge-choice]').forEach(b=>b.disabled=false)}finally{mutateEnd()}
 });
}
function setupSuggestions(modal){const area=modal.querySelector('textarea[name=body]'),box=modal.querySelector('.suggestions');let choices=[],from=0,to=0,active=0;function close(){choices=[];box.hidden=true;box.innerHTML=''}function choose(i){const item=choices[i];if(!item)return;area.setRangeText(item.insert+' ',from,to,'end');close();area.focus()}function update(){const pos=area.selectionStart,before=area.value.slice(0,pos),m=before.match(/(?:^|[\s(])([@#])([\p{L}\p{N}_]{0,32})$/u);if(!m){close();return}const prefix=m[1],q=m[2].toLowerCase();from=pos-m[2].length-1;to=pos;if(prefix==='@'){choices=P.profiles.filter(x=>(x.username+' '+x.display_name).toLowerCase().includes(q)).slice(0,5).map(x=>({insert:'@'+x.username,title:x.display_name,sub:'@'+x.username,id:x.id}))}else{const tags=['игры','технологии','творчество'];P.posts.forEach(p=>{for(const t of (p.body||'').match(/#[\p{L}\p{N}_]{1,32}/gu)||[])tags.push(t.slice(1))});choices=[...new Set(tags.map(x=>x.toLowerCase()))].filter(t=>t.includes(q)).slice(0,5).map(t=>({insert:'#'+t,title:'#'+t,sub:'тема'}))}if(!choices.length){close();return}active=0;box.hidden=false;box.innerHTML=choices.map((c,i)=>`<button type="button" class="suggestion" data-choice="${i}"><span>${esc(c.title)}${c.id?badge(c.id):''}</span><small>${esc(c.sub)}</small></button>`).join('');box.querySelectorAll('[data-choice]').forEach(btn=>btn.onpointerdown=ev=>{ev.preventDefault();choose(Number(btn.dataset.choice))})}area.addEventListener('input',update);area.addEventListener('click',update);area.addEventListener('keydown',ev=>{if(box.hidden)return;if(ev.key==='ArrowDown'||ev.key==='ArrowUp'){ev.preventDefault();active=(active+(ev.key==='ArrowDown'?1:-1)+choices.length)%choices.length;box.querySelectorAll('.suggestion').forEach((b,i)=>b.classList.toggle('selected',i===active))}else if(ev.key==='Enter'||ev.key==='Tab'){ev.preventDefault();choose(active)}else if(ev.key==='Escape'){ev.stopPropagation();close()}})}

function stopViews(){if(P.viewObserver){P.viewObserver.disconnect();P.viewObserver=null}for(const timer of P.viewTimers.values())clearTimeout(timer);P.viewTimers.clear()}
function observeViews(){stopViews();if(!P.session||P.page!=='feed'||document.visibilityState!=='visible'||!('IntersectionObserver' in window))return;P.viewObserver=new IntersectionObserver(entries=>{for(const entry of entries){const id=entry.target.dataset.post,post=P.posts.find(p=>p.id===id);if(!id||!post||post.author_id===P.session?.user.id||P.viewSeen.has(id)||P.viewPending.has(id))continue;if(entry.isIntersecting&&entry.intersectionRatio>=0.2){if(!P.viewTimers.has(id)){const timer=setTimeout(()=>{P.viewTimers.delete(id);if(document.visibilityState==='visible'&&P.page==='feed')recordView(id)},1000);P.viewTimers.set(id,timer)}}else if(P.viewTimers.has(id)){clearTimeout(P.viewTimers.get(id));P.viewTimers.delete(id)}}},{threshold:[0,0.2]});document.querySelectorAll('#main [data-post]').forEach(el=>P.viewObserver.observe(el))}
async function recordView(id){if(!P.session||P.viewSeen.has(id)||P.viewPending.has(id))return;const uid=P.session.user.id;P.viewPending.add(id);mutateStart();try{const total=Number(check(await P.client.rpc('pear_record_post_view',{p_post_id:id})));if(P.session?.user.id!==uid)return;if(!Number.isFinite(total)||total<0)throw Error('Invalid view count');P.viewSeen.add(id);let found=P.views.find(v=>v.post_id===id);if(found)found.total=total;else P.views.push({post_id:id,total});document.querySelectorAll('[data-view-count]').forEach(n=>{if(n.dataset.viewCount===id)n.textContent=String(total)})}catch(err){console.warn('view was not recorded',err)}finally{P.viewPending.delete(id);mutateEnd()}}
async function initializeSession(){if(!P.session)return;const uid=P.session.user.id;try{const profile=check(await P.client.from('profiles').select('id,username,display_name,username_confirmed').eq('id',uid).single());if(P.session?.user.id!==uid)return;if(!profile)throw Error('Профиль не найден.');if(profile.username_confirmed===false){onboarding(profile);return}P.page='feed';P.profileId=uid;P.tab='new';P.query='';P.adminQuery='';Chats.restoreSelection(null);restoreLocation(uid);createShell();await load();if(P.session?.user.id===uid){startRealtime();if(P.loaded)Chats.onNavigate();if(P.page==='admin'){refreshAdminStats();refreshReports()}}}catch(err){root.innerHTML=`<main class="auth-wrap"><section class="auth"><h1>Не удалось открыть профиль</h1><p class="error">${esc(err.message)}</p><p>Убедись, что обновление базы выполнено, и попробуй ещё раз.</p><button class="quiet" id="retry-session">Повторить</button></section></main>`;document.getElementById('retry-session')?.addEventListener('click',initializeSession)}}
function onboarding(profile){root.innerHTML=`<main class="welcome-wrap"><section class="welcome"><div class="welcome-kicker"><span></span> ПОЧТИ ГОТОВО</div><h1>Как тебя называть?</h1><p class="welcome-desc">Придумай уникальный ник — по нему тебя найдут друзья в Pear.</p><form id="onboard-form"><label class="label" for="onboard-username">Твой ник</label><div class="username-control"><span aria-hidden="true">@</span><input id="onboard-username" name="username" maxlength="25" required autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="your_name" aria-describedby="onboard-hint"></div><p id="onboard-hint" class="hint">От 3 до 24 символов: латинские буквы, цифры и _</p><p class="error" id="error" hidden></p><button class="primary welcome-submit" type="submit">Продолжить <span aria-hidden="true">→</span></button></form><p class="welcome-foot">Позже ник можно изменить в профиле.</p></section></main>`;const form=document.getElementById('onboard-form');form.onsubmit=async ev=>{ev.preventDefault();const username=form.elements.username.value.trim().replace(/^@/,''),btn=form.querySelector('button');if(!/^[A-Za-z0-9_]{3,24}$/.test(username))return error('Ник должен содержать от 3 до 24 латинских букв, цифр или _.');btn.disabled=true;btn.textContent='Сохраняем…';try{const values={username,username_confirmed:true};if(!profile.display_name||profile.display_name==='Новый пользователь')values.display_name=username;check(await P.client.from('profiles').update(values).eq('id',profile.id));if(P.session?.user.id!==profile.id)return;await initializeSession()}catch(err){error(err.code==='23505'?'Этот ник уже занят. Попробуй другой.':'Не удалось сохранить ник: '+err.message);btn.disabled=false;btn.textContent='Продолжить →'}}}

(async()=>{try{const r=await fetch('/api/config',{cache:'no-store'}),cfg=await r.json();if(!r.ok||!cfg.url||!cfg.key)throw Error(cfg.error||'Не заданы настройки Supabase.');P.client=createClient(cfg.url,cfg.key);let s=check(await P.client.auth.getSession());P.session=s.session;P.client.auth.onAuthStateChange((event,session)=>{if(event==='INITIAL_SESSION')return;const before=P.session?.user?.id;P.session=session;if(!session){resetProfileTaps();Chats.stop();Notifications.stop();clearInterval(P.interval);clearTimeout(P.refreshTimer);stopViews();if(P.realtime)P.client.removeChannel(P.realtime);P.loaded=false;P.me=null;P.posts=[];P.postId=null;P.detailPost=null;P.replyTargets={};P.pins=[];P.reports=[];P.reportsLoaded=false;P.reportsError=false;P.mediaCleanup=[];P.cleanupError=false;P.profiles=[];P.likes=[];P.comments=[];P.follows=[];P.verified=[];P.views=[];P.viewSeen.clear();P.isAdmin=false;P.isModerator=false;P.moderators=[];P.moderatorsError=false;P.stats=null;P.heartbeatAt=0;P.expanded.clear();authPage()}else if(before!==session.user.id){P.loaded=false;P.page='feed';P.viewSeen.clear();setTimeout(initializeSession,0)}});if(!P.session){authPage();return}await initializeSession();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){scheduleLoad(200);activityPing();observeViews();Chats.refresh();Chats.refreshUnread();Notifications.refresh()}else stopViews()})}catch(err){root.innerHTML=`<main class="auth-wrap"><section class="auth"><h1>Нужна настройка</h1><p class="error">${esc(err.message)}</p><p>Проверь настройки Supabase на сервере.</p></section></main>`}})();
